#!/usr/bin/env node
/**
 * No-Playwright path for capturing a DeepSeek auth token.
 *
 * Flow:
 *   1. Run this script. It starts a tiny HTTP server on localhost:9876.
 *   2. Open http://localhost:9876 in your normal browser. The page hosts
 *      a `javascript:` bookmarklet you drag to your bookmarks bar.
 *   3. Open https://chat.deepseek.com in another tab and sign in normally.
 *   4. Click the bookmark. It reads `localStorage.userToken`, unwraps the
 *      `{value: "..."}` shape DeepSeek uses, and POSTs the bare token back
 *      to this server. The browser allows https→http://localhost (treated
 *      as secure context). We use a `text/plain` body so no CORS preflight
 *      is needed (simple-request rules).
 *   5. The server verifies the token against /api/v0/users/current, writes
 *      it to ./.env as `DEEPSEEK_USER_TOKEN=<token>`, prints success, and
 *      exits.
 *
 * Tradeoffs vs. extract-ai-token.mjs (the Playwright path):
 *   + No Chromium download, no persistent profile dir, works with the user's
 *     own browser including extensions.
 *   - Requires one manual click per refresh (Playwright path can be invoked
 *     programmatically from tokenManager.refreshToken()).
 */
import http from "node:http";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const PORT      = Number(process.env.BOOKMARKLET_PORT ?? 9876);
const ROOT      = process.env.AI_PROVIDERS_CONSUMER_ROOT ?? process.cwd();
const ENV_PATH  = join(ROOT, ".env");
const TARGET    = "https://chat.deepseek.com";
const TIMEOUT_MS = 5 * 60_000; // 5 minutes to click the bookmark

// The bookmarklet — kept on one logical line for the href. We unwrap the
// stored entry (DeepSeek stores `{value: "<token>", __version: "0"}` so
// raw localStorage reads return the wrapper, not the token). text/plain
// body avoids CORS preflight.
// Bookmarklet:
//   - First guards against the most common user mistake: clicking it while
//     the active tab is the setup page (localhost) instead of chat.deepseek.com.
//     localStorage is per-origin, so reading from the wrong tab returns nothing.
//   - Scans EVERY localStorage / sessionStorage / cookie value (not a hardcoded
//     key list) for a token-shaped string. DeepSeek has changed the storage
//     key across versions, and scanning is cheap.
//   - Unwraps the common `{value: "<token>", __version: "0"}` shape DeepSeek
//     uses for storage entries.
const BOOKMARKLET = `javascript:(async()=>{try{if(!location.hostname.includes('deepseek')){alert('You are on '+location.hostname+'. Switch to the chat.deepseek.com tab FIRST, then click this bookmark.');return;}const looksLike=(s)=>typeof s==='string'&&s.length>=30&&s.length<=2048&&/^[A-Za-z0-9+/=._\\-]+$/.test(s);const unwrap=(raw)=>{if(!raw)return null;if(looksLike(raw))return raw;try{const j=JSON.parse(raw);if(j&&typeof j==='object'){for(const k of ['value','token','accessToken','access_token','authToken','userToken','bearerToken']){if(looksLike(j[k]))return j[k];}}}catch{}return null;};let tok=null;for(let i=0;i<localStorage.length;i++){const v=unwrap(localStorage.getItem(localStorage.key(i)));if(v){tok=v;break;}}if(!tok)for(let i=0;i<sessionStorage.length;i++){const v=unwrap(sessionStorage.getItem(sessionStorage.key(i)));if(v){tok=v;break;}}if(!tok)for(const c of document.cookie.split(';')){const eq=c.indexOf('=');if(eq<0)continue;const v=decodeURIComponent(c.slice(eq+1).trim());if(looksLike(v)){tok=v;break;}}if(!tok){alert('No token-shaped value found in storage on '+location.hostname+'. Make sure you are signed in.');return;}const res=await fetch('http://localhost:${PORT}/token',{method:'POST',headers:{'content-type':'text/plain'},body:tok});const t=await res.text();alert(res.ok?'Token captured! Return to the terminal.':'Server error: '+t);}catch(e){alert('Capture failed: '+e.message);}})();`;

const SETUP_HTML = `<!doctype html>
<html lang="ar" dir="rtl">
<head>
<meta charset="utf-8">
<title>DeepSeek Token Capture</title>
<style>
  body { font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
         max-width: 720px; margin: 2rem auto; padding: 0 1rem;
         color: #1f2937; line-height: 1.7; }
  h1 { color: #4338ca; }
  ol li { margin: 0.8rem 0; }
  code { background: #f3f4f6; padding: 0.15rem 0.4rem; border-radius: 4px;
         font-size: 0.92em; }
  .bm { display: inline-block; padding: 0.6rem 1.1rem; background: #4338ca;
        color: #fff !important; text-decoration: none; border-radius: 8px;
        font-weight: 600; user-select: none; }
  .bm:hover { background: #3730a3; }
  .hint { background: #fef3c7; border-right: 4px solid #f59e0b;
          padding: 0.6rem 1rem; margin: 1rem 0; border-radius: 6px; }
  .ok { background: #dcfce7; border-right: 4px solid #16a34a;
        padding: 0.6rem 1rem; margin: 1rem 0; border-radius: 6px;
        display: none; }
  .latin { direction: ltr; text-align: left; }
</style>
</head>
<body>
  <h1>التقاط توكن DeepSeek</h1>

  <p>اتبع الخطوات بالترتيب:</p>

  <ol>
    <li>
      اسحب هذا الزرّ إلى شريط المفضّلة في متصفّحك
      (سيظهر كإشارة مرجعيّة):<br><br>
      <a class="bm" href="${BOOKMARKLET}">Get DeepSeek Token</a>
    </li>
    <li>
      افتح <a href="${TARGET}" target="_blank" rel="noopener">chat.deepseek.com</a>
      في تبويب آخر وسجّل الدخول كالمعتاد.
    </li>
    <li>
      <strong>تأكّد أن تبويب chat.deepseek.com هو التبويب النشِط</strong>
      (وليس هذه الصفحة)، ثم اضغط الإشارة المرجعيّة
      <span class="latin"><strong>Get DeepSeek Token</strong></span>
      التي سحبتها. الـbookmarklets تقرأ بيانات التبويب المعروض فقط، فإن
      ضغطتها هنا ستفشل لأن localStorage يختلف بين النطاقات.
    </li>
    <li>
      سترى رسالة <em>"Token captured!"</em> — عُد إلى الطرفية، التوكن
      حُفظ في <code>.env</code> تلقائيًّا والسكربت أغلق نفسه.
    </li>
  </ol>

  <div class="hint">
    لا يعمل سحب الزرّ؟ انقر عليه بزرّ الفأرة الأيمن → "Bookmark Link"
    (Firefox) أو "Add to Bookmarks" (Chrome/Edge). أو افتح Console في
    صفحة DeepSeek بعد تسجيل الدخول والصق سطر JavaScript أدناه:
    <pre class="latin" style="white-space:pre-wrap;word-break:break-all;font-size:.8em">${BOOKMARKLET.replace(/</g,"&lt;")}</pre>
  </div>

  <div class="ok" id="ok">تمّ — يمكنك إغلاق هذه الصفحة.</div>

  <script>
    // Poll the server so the page tells the user when capture is done.
    (async () => {
      while (true) {
        await new Promise(r => setTimeout(r, 1500));
        try {
          const r = await fetch('/status');
          const j = await r.json();
          if (j.captured) {
            document.getElementById('ok').style.display = 'block';
            return;
          }
        } catch { return; /* server shut down */ }
      }
    })();
  </script>
</body>
</html>`;

let captured = false;
let result = null;

function setCors(res, origin) {
  // Bookmarklet runs inside chat.deepseek.com. Allow that exact origin and
  // a few obvious fallbacks. text/plain bodies don't trigger preflight, so
  // we only really need Allow-Origin on the actual response.
  const allowed = new Set([
    "https://chat.deepseek.com",
    "http://localhost:" + PORT,
    "http://127.0.0.1:" + PORT,
  ]);
  if (origin && allowed.has(origin)) {
    res.setHeader("access-control-allow-origin", origin);
  } else {
    res.setHeader("access-control-allow-origin", "*");
  }
  res.setHeader("access-control-allow-methods", "POST, GET, OPTIONS");
  res.setHeader("access-control-allow-headers", "content-type");
}

async function verify(token) {
  try {
    const r = await fetch(`${TARGET}/api/v0/users/current`, {
      headers: { authorization: `Bearer ${token}`, "content-type": "application/json" },
    });
    if (!r.ok) return { ok: false, status: r.status };
    const body = await r.json().catch(() => ({}));
    const data = body?.data?.biz_data;
    const identity = data?.email ?? data?.name ?? data?.username ?? null;
    return identity ? { ok: true, identity } : { ok: false, status: 200, reason: "anonymous" };
  } catch (e) {
    return { ok: false, status: 0, reason: e.message };
  }
}

function writeEnv(token) {
  let body = "";
  if (existsSync(ENV_PATH)) {
    body = readFileSync(ENV_PATH, "utf8");
  }
  const line = `DEEPSEEK_USER_TOKEN=${token}`;
  if (/^DEEPSEEK_USER_TOKEN=.*$/m.test(body)) {
    body = body.replace(/^DEEPSEEK_USER_TOKEN=.*$/m, line);
  } else {
    body = (body.endsWith("\n") || body === "" ? body : body + "\n") + line + "\n";
  }
  writeFileSync(ENV_PATH, body, "utf8");
}

const server = http.createServer(async (req, res) => {
  const origin = req.headers.origin;
  setCors(res, origin);

  if (req.method === "OPTIONS") {
    res.writeHead(204);
    res.end();
    return;
  }

  if (req.method === "GET" && (req.url === "/" || req.url === "/index.html")) {
    res.writeHead(200, { "content-type": "text/html; charset=utf-8" });
    res.end(SETUP_HTML);
    return;
  }

  if (req.method === "GET" && req.url === "/status") {
    res.writeHead(200, { "content-type": "application/json" });
    res.end(JSON.stringify({ captured }));
    return;
  }

  if (req.method === "POST" && req.url === "/token") {
    let body = "";
    req.on("data", (chunk) => { body += chunk; if (body.length > 8192) req.destroy(); });
    req.on("end", async () => {
      const token = body.trim();
      if (!token || token.length < 20 || token.startsWith("{")) {
        res.writeHead(400, { "content-type": "text/plain; charset=utf-8" });
        res.end("invalid token shape");
        return;
      }
      const v = await verify(token);
      if (!v.ok) {
        res.writeHead(400, { "content-type": "text/plain; charset=utf-8" });
        res.end(`verification failed: ${v.reason ?? "HTTP " + v.status}`);
        return;
      }
      writeEnv(token);
      captured = true;
      result = { token, identity: v.identity };
      res.writeHead(200, { "content-type": "text/plain; charset=utf-8" });
      res.end("ok");
      // Give the bookmarklet time to read the response before we shut down.
      setTimeout(() => server.close(), 500);
    });
    return;
  }

  res.writeHead(404, { "content-type": "text/plain" });
  res.end("not found");
});

server.listen(PORT, "127.0.0.1", () => {
  console.log(`\n  DeepSeek token capture server`);
  console.log(`  ─────────────────────────────`);
  console.log(`  Open this URL in your browser:\n`);
  console.log(`      http://localhost:${PORT}\n`);
  console.log(`  Follow the on-page instructions. Waiting up to ${TIMEOUT_MS / 60_000} min...\n`);
});

server.on("close", () => {
  if (result) {
    console.log(`\n  ✓ Token captured (verified as: ${result.identity})`);
    console.log(`  ✓ Saved to ${ENV_PATH}\n`);
    process.exitCode = 0;
  } else {
    console.log(`\n  ✗ Timed out without capturing a token.\n`);
    process.exitCode = 2;
  }
});

setTimeout(() => {
  if (!captured) {
    console.log("\n  Timeout — closing server.");
    server.close();
  }
}, TIMEOUT_MS);
